package main

import "github.com/egoist/mygo/ui"

// The icons the interface draws, from the Phosphor set
// (https://phosphoricons.com, MIT). Each is a fill drawing on a 256-unit
// box, tinted with the element's text color. The regular weight carries
// the interface's controls; the kind glyphs that stand large on the file
// cards take the fill weight, which reads at that size.

// ph builds one icon from the inner markup of its SVG.
func ph(shapes string) *ui.SVG {
	return ui.MustParseSVG([]byte(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" fill="currentColor">` + shapes + `</svg>`))
}

