// kindIcon names the glyph a file kind shows, on the table's rows and the
// grid's cards.
func kindIcon(k fileKind) *ui.SVG {
	switch k {
	case kindFolder:
		return iconFolder
	case kindImage:
		return iconImage
	case kindAudio:
		return iconAudio
	case kindVideo:
		return iconVideo
	case kindArchive:
		return iconArchive
	case kindDocument:
		return iconDocument
	default:
		return iconOther
	}
}

// iconFor names a glyph for the menus, which refer to icons by name so
// that a menu can be built from data.
func iconFor(name string) *ui.SVG {
	switch name {
	case "dashboard":
		return iconDashboard
	case "files":
		return iconFiles
	case "recent":
		return iconRecent
	case "settings":
		return iconSettings
	case "sliders":
		return iconSliders
	case "bucket":
		return iconBucket
	case "plus":
		return iconPlus
	case "close":
		return iconClose
	case "check":
		return iconCheck
	case "folder":
		return iconFolder
	case "newfolder":
		return iconNewFolder
	case "upload":
		return iconUpload
	case "download":
		return iconDownload
	case "trash":
		return iconTrash
	case "rename":
		return iconRename
	case "move":
		return iconMove
	case "share":
		return iconShare
	case "link":
		return iconLink
	case "copy":
		return iconCopy
	case "eye":
		return iconEye
	case "external":
		return iconExternal
	case "refresh":
		return iconRefresh
	case "search":
		return iconSearch
	case "grid":
		return iconGrid
	case "list":
		return iconList
	case "up":
		return iconUp
	case "more":
		return iconMore
	case "info":
		return iconInfo
	case "alert":
		return iconAlert
	case "transfer":
		return iconTransfer
	case "cloud":
		return iconCloud
	case "lock":
		return iconLock
	case "terminal":
		return iconTerminal
	case "sparkle":
		return iconSparkle
	default:
		return iconOther
	}
}
